<?php require_once __DIR__.'/../includes/functions.php';$u=require_login();verify_csrf();$to=(int)($_POST['receiver_id']??0);$msg=trim($_POST['message']??'');$q=db()->prepare("SELECT COUNT(*) FROM study_requests WHERE status='accepted' AND ((sender_id=? AND receiver_id=?) OR (sender_id=? AND receiver_id=?))");$q->execute([(int)$u['id'],$to,$to,(int)$u['id']]);if($to===(int)$u['id']||!$q->fetchColumn()||$msg===''||mb_strlen($msg)>2000){flash('danger','Message could not be sent. Check that you are connected and the message is under 2,000 characters.');go('../student/messages.php');}db()->prepare('INSERT INTO messages(sender_id,receiver_id,message) VALUES(?,?,?)')->execute([(int)$u['id'],$to,$msg]);notify($to,'New message from '.$u['name'].'.','messages.php?user='.(int)$u['id']);go('../student/messages.php?user='.$to);
